#!/usr/bin/env python3
#
# EtherADAT bridge top-level for the ADATface board: 3 ADAT inputs and
# 2 ADAT outputs bridged to raw-Ethernet AdatNet frames (PROTOCOL.md,
# role 1 = the RP2350 part) over an RMII-attached LAN8720 PHY.
#
# The Ethernet MAC is `liteeth_etheradat_mac.v` (generated by
# etheradat/liteeth/gen_etheradat_mac.py): the proven RMII shim + the
# same clock-domain-crossing fix as the working UDP/IP baseline, with
# the LiteEth MAC user streams exposed. The bridge core speaks the
# LiteEth MAC user-stream contract (frames without preamble/FCS).
#
# Build (from gateware/, project venv activated):
#   python etheradat/scripts/generate_quartus_files_etheradat.py <dir>
#     [--ref-clk-mode input|output]
#
# Wiring (J7 -> LAN8720 module), full table and PHY strap notes in
# etheradat/README.md.
#
# Bring-up UART (115200, pin J_2:34, clocked from the board's 50 MHz
# oscillator so it survives a dead REF_CLK):
#   dump = AA 01 <NV x u16 LE> 5A, every 250 ms:
#     [0] TX audio frames sent to the MAC   [1] RX audio frames parsed
#     [2] hello frames sent                 [3] valid PC hellos seen
#     [4] ADAT blocks built (fast domain)   [5] feeder buffer consumes
#     [6] RX frames with errors             [7] TX block drops (builder)
#     [8] frames filtered (dst/type/src)    [9] ADAT transmitter underflows
#    [10] status0: link, pc_linked, free_run, synced[0..2], phy_found
#    [11] status1: feeder active/committing, REF_CLK level, CRS_DV, ...
#    [12] discovery linked (bridged level)
#    [13] hello-due pulses (4/s while discovering)
#    [14..] MAC short-frame counters, TX byte-capture taps
#    [56..] RX-side bring-up taps for input0 (IN1): channel/frame counts,
#           collector ring wraps, sync state (see the RX-tap comment below)
#   etheradat/bringup_tools/parse_eduart.py decodes the whole dump.
#
# A dead RMII REF_CLK (PHY unpowered / wrong strap) shows as:
#   build stalls at 2, tx_frames = 0, hello_tx = 0, tx_drops ~3200/s.
# With a live REF_CLK and no PC: tx_frames = build = 3200/s, hello = 4/s.
#
# The interface is the ADAT master: the ADAT outputs are generated from
# the local 12.288 MHz audio clock; the inputs are recovered from the
# incoming optical streams. With no synced ADAT input the TX direction
# free-runs at exactly 3200 blocks/s with EMPTY_USER_FRAME silence.

import os
import sys

from amaranth            import *
from amaranth.build      import Attrs, Pins, Resource, Subsignal
from amaranth.lib.cdc    import FFSynchronizer

from luna                import top_level_cli

from adat import ADATTransmitter, ADATReceiver

from etheradat.audio_payload import gray2bin2_terms
from etheradat.bridge import EtherADATBridge, RMIIClockDomain


def _pulse_to(m, sig, src, dst, name, cycles=4):
    """Stretch a one-cycle pulse in `src`, then synchronize + edge-detect
    it in `dst` (the two 50 MHz clocks may be asynchronous)."""
    hold = Signal(cycles, name=name + "_hold")
    m.d[src] += hold.eq(Cat(hold[1:], sig))
    s = Signal(name=name + "_s")
    m.submodules += FFSynchronizer(hold != 0, s, o_domain=dst)
    prev = Signal(name=name + "_prev")
    m.d[dst] += prev.eq(s)
    return s & ~prev


def _toggle_to(m, tg, dst, name):
    """Synchronize a toggle bit from a fast domain into `dst` and return a
    one-cycle pulse in `dst` for every toggle.  Used for rare events
    (anomalies) where the source may be many times faster than `dst`; the
    event rate itself must stay below the `dst` rate."""
    s = Signal(name=name + "_s")
    m.submodules += FFSynchronizer(tg, s, o_domain=dst)
    prev = Signal(name=name + "_prev")
    m.d[dst] += prev.eq(s)
    return s ^ prev


def _count(m, event, dst, name, width=16):
    cnt = Signal(width, name=name)
    with m.If(event):
        m.d[dst] += cnt.eq(cnt + 1)
    return cnt


def _gray_counter_count(m, gray, src, dst, name):
    """Count increments of a 2-bit gray mailbox counter across domains."""
    g = Signal(2, name=name + "_gray")
    m.submodules += FFSynchronizer(gray, g, o_domain=dst)
    b1, b0 = gray2bin2_terms(g[1], g[0])
    b = Signal(2, name=name + "_bin")
    prev = Signal(2, name=name + "_prev")
    m.d.comb += b.eq(Cat(b0, b1))
    m.d[dst] += prev.eq(b)
    return _count(m, b != prev, dst, name)


class EtherADATInterface(Elaboratable):
    """EtherADAT bridge (role 1) on the ADATface baseboard.

    Parameters
    ----------
    ref_clk_mode : "input" — the LAN8720 module generates the 50 MHz RMII
        reference (25 MHz crystal, REF_CLK-OUT strap; the configuration
        that worked on hardware 22.11.2026); "output" — the FPGA drives
        the reference from the board's 50 MHz oscillator (module must be
        strapped REF_CLK-in / nINTSEL).
    """

    def __init__(self, ref_clk_mode="input", own_mac=0x02AD6E657401,
                 device_serial=0x41444146, session_nonce=0,
                 audio_tx_enable=True, tx_negedge=False,
                 mon_source="ref", debug_taps=True, mon_pll_src="clk50"):
        assert ref_clk_mode in ("input", "output")
        # REF_CLK integrity monitor source: "ref" = the RMII REF_CLK pin,
        # "clk50" = the board's own 50 MHz oscillator (control build: the
        # monitor PLL is fed by that same oscillator, so every interval
        # must be exactly 6 ticks unless the monitor itself produces
        # artifacts); "none" = no monitor PLL (Cyclone V has a tight PLL
        # budget / for production builds).
        assert mon_source in ("ref", "clk50", "none")
        self.mon_source = mon_source
        # mon_pll_src: monitor PLL reference.  "clk50" is the normal
        # independent reference; "ref" feeds the PLL from the REF_CLK pin
        # itself (capability probe: is that pin a PLL input on this
        # device?  Also the basis for a REF_CLK cleanup PLL).
        assert mon_pll_src in ("clk50", "ref")
        self.mon_pll_src = mon_pll_src
        # debug_taps: dump the 16-byte TX captures/payload taps.  Turning
        # them off saves the per-byte CDC registers and lets the design
        # fit the Cyclone V A2 (943 LABs).
        self.debug_taps = debug_taps
        self.ref_clk_mode = ref_clk_mode
        self.audio_tx_enable = audio_tx_enable
        self.tx_negedge = tx_negedge
        self.own_mac = own_mac
        self.device_serial = device_serial
        self.session_nonce = session_nonce

    def elaborate(self, platform):
        m = Module()

        # Board oscillator: 50 MHz, always present.
        clk_pin = platform.request(platform.default_clk)

        # Audio/ADAT clock domains (usb/sync/fast/adat/dac) from the PLLs.
        m.submodules.car = car = platform.clock_domain_generator(
            clk_input=clk_pin.i)

        # Debug/UART domain: the board's 50 MHz oscillator, with the
        # probe-style inline UART. (The modular PeriodicDump/UartTX
        # block simulates correctly but produces no activity on
        # hardware; it is deliberately not used here.)
        m.domains.sys = ClockDomain()
        m.d.comb += ClockSignal("sys").eq(clk_pin.i)
        D = "sys"

        #
        # RMII pads + reference clock
        #
        if self.ref_clk_mode == "output":
            rmii = platform.request("rmii", 0, dir={"ref_clk": "o"})
            m.d.comb += rmii.ref_clk.o.eq(clk_pin.i)
            rmii_clk = clk_pin.i
        else:
            rmii = platform.request("rmii", 0, dir={"ref_clk": "i"})
            rmii_clk = rmii.ref_clk.i

        m.submodules.rmii_domain = rmii_domain = RMIIClockDomain()
        m.d.comb += [
            rmii_domain.clk_in.eq(rmii_clk),
            rmii_domain.rst_in.eq(0),
        ]

        #
        # REF_CLK integrity monitor (diagnostic).
        #
        # The observed TX/RX corruption is a serializer slip that needs an
        # occasional skipped REF_CLK edge.  A 150 MHz oversampler saw
        # intervals stretched from 3 to 6 ticks; this monitor re-measures
        # the same input at 250 MHz (dedicated ALTPLL, VCO 750 MHz / 3),
        # 4 ns per tick, which also exposes *short*/runt pulses that the
        # 150 MHz monitor could not resolve.
        #
        # In the 250 MHz domain a 50 MHz period is nominally 5 ticks.
        # The 2-FF synchronizer adds 0..2 ticks of edge-position jitter,
        # so normal intervals are 3..7 ticks, and a *synchronous* source
        # (the --mon-source clk50 control build) shows no events at all.
        # Bins (validated against that control):
        #   <=2    short   : synchronizer jitter, NOT a line defect
        #   8..9   stretch : 32-36 ns, slow edge / threshold shift
        #   10..12 skip    : 40-48 ns = exactly one missing REF_CLK edge
        #   >=13   vlong   : two or more missing edges
        # Only stretch/skip/vlong exceed the jitter bound.  The counters
        # and the last event (its gap, the gap before it, the kind, and
        # the monitor-PLL lock) are crossed into the UART domain via
        # toggle bits.  8 extra dump values:
        #   c_ref_alive, c_ref_short, c_ref_stretch, c_ref_skip,
        #   c_ref_vlong, prev_gap, gap | kind[11:8] | locked[12],
        #   build marker.
        # The monitor only exists in input mode (in output mode the pin
        # is driven by the FPGA and there is nothing to observe).
        #
        ref_mon_values = [Const(0, 16)] * 8
        if self.ref_clk_mode == "input" and self.mon_source != "none":
            mon_clk = Signal(name="mon_clk_250")
            mon_locked = Signal(name="mon_locked")
            m.submodules.mon_pll = Instance("ALTPLL",
                p_BANDWIDTH_TYPE         = "AUTO",
                p_CLK0_DIVIDE_BY         = 3,
                p_CLK0_DUTY_CYCLE        = 50,
                p_CLK0_MULTIPLY_BY       = 15,
                p_CLK0_PHASE_SHIFT       = 0,
                p_INCLK0_INPUT_FREQUENCY = 20000,
                p_OPERATION_MODE         = "NORMAL",
                i_inclk  = clk_pin.i,
                o_clk    = mon_clk,
                o_locked = mon_locked,
            )
            m.domains.mon = ClockDomain()
            m.d.comb += ClockSignal("mon").eq(mon_clk)

            # 2-FF synchronizer (FFSynchronizer) + one history FF in the
            # monitor domain.  The edge MUST be derived from the
            # synchronizer output, not from the first sampling FF: the
            # first FF can go metastable and then both loses real edges
            # and fabricates short ones (measured as a 55k/s "short gap"
            # storm at idle before this was fixed).
            mon_sig = (clk_pin.i if self.mon_source == "clk50"
                       else rmii.ref_clk.i)
            ref_f = Signal(name="mon_ref")
            m.submodules += FFSynchronizer(mon_sig, ref_f, o_domain="mon")
            ref_fd = Signal(name="mon_ref_d")
            m.d.mon += ref_fd.eq(ref_f)
            ref_edge = Signal(name="mon_ref_edge")
            m.d.comb += ref_edge.eq(ref_f & ~ref_fd)

            gap_cnt = Signal(8, name="mon_gap_cnt")
            last_gap = Signal(8, name="mon_last_gap")
            prev_gap_l = Signal(8, name="mon_prev_gap")
            last_kind = Signal(4, name="mon_last_kind")
            short_tg = Signal(name="mon_short_tg")
            stretch_tg = Signal(name="mon_stretch_tg")
            skip_tg = Signal(name="mon_skip_tg")
            vlong_tg = Signal(name="mon_vlong_tg")
            last_tg = Signal(name="mon_last_tg")
            alive_div = Signal(12, name="mon_alive_div")
            alive_tg = Signal(name="mon_alive_tg")

            m.d.mon += alive_div.eq(alive_div + 1)
            with m.If(alive_div == 0):
                m.d.mon += alive_tg.eq(~alive_tg)

            with m.If(ref_edge):
                m.d.mon += [last_gap.eq(gap_cnt), gap_cnt.eq(0)]
            with m.Else():
                m.d.mon += gap_cnt.eq(gap_cnt + 1)

            is_short = gap_cnt <= 2
            is_stretch = (gap_cnt >= 8) & (gap_cnt < 10)
            is_skip = (gap_cnt >= 10) & (gap_cnt < 13)
            is_vlong = gap_cnt >= 13
            with m.If(ref_edge & is_short):
                m.d.mon += short_tg.eq(~short_tg)
            with m.If(ref_edge & is_stretch):
                m.d.mon += stretch_tg.eq(~stretch_tg)
            with m.If(ref_edge & is_skip):
                m.d.mon += skip_tg.eq(~skip_tg)
            with m.If(ref_edge & is_vlong):
                m.d.mon += vlong_tg.eq(~vlong_tg)
            with m.If(ref_edge & (is_short | is_stretch | is_skip | is_vlong)):
                m.d.mon += [
                    last_tg.eq(~last_tg),
                    last_kind.eq(Cat(is_short, is_stretch, is_skip,
                                     is_vlong)),
                    prev_gap_l.eq(last_gap),
                ]

            gap_d = Signal(8, name="mon_gap_d")
            prev_d = Signal(8, name="mon_prev_d")
            kind_d = Signal(4, name="mon_kind_d")
            locked_d = Signal(name="mon_locked_d")
            m.submodules += [
                FFSynchronizer(last_gap, gap_d, o_domain=D),
                FFSynchronizer(prev_gap_l, prev_d, o_domain=D),
                FFSynchronizer(last_kind, kind_d, o_domain=D),
                FFSynchronizer(mon_locked, locked_d, o_domain=D),
            ]
            gap_latch = Signal(8, name="mon_gap_latch")
            prev_latch = Signal(8, name="mon_prev_latch")
            kind_latch = Signal(4, name="mon_kind_latch")
            lock_latch = Signal(name="mon_lock_latch")
            last_ev = _toggle_to(m, last_tg, D, "ev_ref_last")
            with m.If(last_ev):
                m.d[D] += [
                    gap_latch.eq(gap_d),
                    prev_latch.eq(prev_d),
                    kind_latch.eq(kind_d),
                    lock_latch.eq(locked_d),
                ]

            ref_mon_values = [
                _count(m, _toggle_to(m, alive_tg, D, "ev_ref_alive"),
                       D, "c_ref_alive"),
                _count(m, _toggle_to(m, short_tg, D, "ev_ref_short"),
                       D, "c_ref_short"),
                _count(m, _toggle_to(m, stretch_tg, D, "ev_ref_stretch"),
                       D, "c_ref_stretch"),
                _count(m, _toggle_to(m, skip_tg, D, "ev_ref_skip"),
                       D, "c_ref_skip"),
                _count(m, _toggle_to(m, vlong_tg, D, "ev_ref_vlong"),
                       D, "c_ref_vlong"),
                Cat(prev_latch, Const(0, 8)),
                Cat(gap_latch, kind_latch, lock_latch, Const(0, 3)),
                Const(0xCA35, 16),
            ]

        #
        # Bridge core
        #
        m.submodules.bridge = bridge = EtherADATBridge(
            own_mac=self.own_mac,
            device_serial=self.device_serial,
            session_nonce=self.session_nonce,
            fast_clk_freq=platform.fast_domain_clock_freq,
            rmii_clk_freq=50_000_000,
            audio_tx_enable=self.audio_tx_enable,
        )

        #
        # LiteEth MAC core (generated Verilog; all clocks = RMII REF_CLK)
        #
        _mac_v = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                              "liteeth", "liteeth_etheradat_mac.v")
        platform.add_file("liteeth_etheradat_mac.v", open(_mac_v, "rb"))

        eth_tx_clk = Signal(name="eth_tx_clk_neg")
        m.d.comb += eth_tx_clk.eq(~rmii_clk if self.tx_negedge else rmii_clk)
        mac_dbg = {n: Signal(name="mac_dbg_" + n) for n in
                   ("sink_frame", "sink_short", "phy_frame", "phy_short")}
        # MAC TX line tap: first 16 bytes entering the RMII serializer
        # (after preamble/CRC) + frame length/count (eth_tx domain)
        mac_cap = [Signal(8, name=f"mac_cap{i}") for i in range(16)]
        mac_cap_len = Signal(16, name="mac_cap_len")
        mac_cap_count = Signal(16, name="mac_cap_count")
        # RMII pin-level reassembly (serializer -> PHY pads)
        mac_pin = [Signal(8, name=f"mac_pin{i}") for i in range(16)]
        mac_pin_len = Signal(16, name="mac_pin_len")
        mac_pin_count = Signal(16, name="mac_pin_count")
        m.submodules.liteeth_mac = Instance("liteeth_etheradat_mac",
            i_sys_clk        = ClockSignal("rmii"),
            i_sys_rst        = ResetSignal("rmii"),
            i_eth_tx_clk     = eth_tx_clk,
            i_eth_tx_rst     = ResetSignal("rmii"),
            i_eth_rx_clk     = ClockSignal("rmii"),
            i_eth_rx_rst     = ResetSignal("rmii"),
            o_rmii_tx_en     = rmii.tx_en.o,
            o_rmii_txd       = Cat(rmii.txd0.o, rmii.txd1.o),
            i_rmii_crs_dv    = rmii.crs_dv.i,
            i_rmii_rxd       = Cat(rmii.rxd0.i, rmii.rxd1.i),
            i_user_sink_payload_data = bridge.mac_tx_data,
            i_user_sink_valid        = bridge.mac_tx_valid,
            i_user_sink_last         = bridge.mac_tx_last,
            o_user_sink_ready        = bridge.mac_tx_ready,
            o_user_source_payload_data = bridge.mac_rx_data,
            o_user_source_valid        = bridge.mac_rx_valid,
            o_user_source_last         = bridge.mac_rx_last,
            o_user_source_payload_error = bridge.mac_rx_error,
            i_user_source_ready        = bridge.mac_rx_ready,
            o_dbg_sink_frame = mac_dbg["sink_frame"],
            o_dbg_sink_short = mac_dbg["sink_short"],
            o_dbg_phy_frame  = mac_dbg["phy_frame"],
            o_dbg_phy_short  = mac_dbg["phy_short"],
            o_dbg_cap_len    = mac_cap_len,
            o_dbg_cap_count  = mac_cap_count,
            **{f"o_dbg_cap{i}": mac_cap[i] for i in range(16)},
            o_dbg_pin_len    = mac_pin_len,
            o_dbg_pin_count  = mac_pin_count,
            **{f"o_dbg_pin{i}": mac_pin[i] for i in range(16)},
        )

        #
        # MDIO (link status only; the PHY runs on strap defaults)
        #
        m.d.comb += [
            rmii.mdc.o.eq(bridge.mdio.mdc_out),
            rmii.mdio.o.eq(bridge.mdio.mdio_o),
            rmii.mdio.oe.eq(bridge.mdio.mdio_oe),
            bridge.mdio.mdio_i.eq(rmii.mdio.i),
        ]

        #
        # TX frame taps (bring-up): the first 16 bytes + length/count of
        # every frame, captured independently on the bridge->MAC side
        # ("sink") and, inside the blackbox, on the MAC->RMII side
        # ("mac"). UART-dumped to locate where leading header bytes go.
        #
        sink_cap = [Signal(8, name=f"sink_cap{i}") for i in range(16)]
        sink_cap_len = Signal(16, name="sink_cap_len")
        sink_cap_count = Signal(16, name="sink_cap_count")
        # first 16 PAYLOAD bytes (frame byte 22..37) as the bridge hands
        # them to the MAC — separates builder/BRAM read from MAC/shim
        sink_pay = [Signal(8, name=f"sink_pay{i}") for i in range(16)]
        sink_idx = Signal(5)
        sink_n = Signal(16)
        with m.If(bridge.mac_tx_valid & bridge.mac_tx_ready):
            with m.If(sink_idx < 16):
                m.d.rmii += Array(sink_cap)[sink_idx[:4]].eq(
                    bridge.mac_tx_data)
            with m.If((sink_n >= 22) & (sink_n < 38)):
                m.d.rmii += Array(sink_pay)[(sink_n - 22)[:4]].eq(
                    bridge.mac_tx_data)
            with m.If(bridge.mac_tx_last):
                m.d.rmii += [
                    sink_cap_len.eq(sink_n + 1),
                    sink_cap_count.eq(sink_cap_count + 1),
                    sink_n.eq(0),
                    sink_idx.eq(0),
                ]
            with m.Else():
                m.d.rmii += sink_n.eq(sink_n + 1)
                with m.If(sink_idx < 16):
                    m.d.rmii += sink_idx.eq(sink_idx + 1)

        #
        # ADAT: 3 receivers (inputs), 2 transmitters (outputs)
        #
        toslink = [platform.request("toslink", i + 1) for i in range(3)]

        receivers = []
        for i in range(3):
            receiver = DomainRenamer("fast")(
                ADATReceiver(platform.fast_domain_clock_freq))
            setattr(m.submodules, f"adat{i}_receiver", receiver)
            receivers.append(receiver)
            m.d.comb += [
                receiver.adat_in.eq(toslink[i].rx.i),
                bridge.builder.sample_in[i].eq(receiver.sample_out),
                bridge.builder.addr_in[i].eq(receiver.addr_out),
                bridge.builder.enable_in[i].eq(receiver.output_enable),
                bridge.builder.user_in[i].eq(receiver.user_data_out),
                bridge.builder.synced_in[i].eq(receiver.synced_out),
            ]

        transmitters = []
        for o in range(2):
            transmitter = ADATTransmitter(fifo_depth=9 * 4)
            setattr(m.submodules, f"adat{o}_transmitter", transmitter)
            transmitters.append(transmitter)
            m.d.comb += [
                toslink[o].tx.o.eq(transmitter.adat_out),
                transmitter.sample_in.eq(bridge.feeder.sample_out[o]),
                transmitter.addr_in.eq(bridge.feeder.addr_out[o]),
                transmitter.valid_in.eq(bridge.feeder.valid_out[o]),
                transmitter.last_in.eq(bridge.feeder.last_out[o]),
                transmitter.user_data_in.eq(bridge.feeder.user_out[o]),
                bridge.feeder.ready_in[o].eq(transmitter.ready_out),
            ]

        #
        # LEDs (bring-up)
        #
        leds = platform.request("leds")
        m.d.comb += [
            leds.host.eq(bridge.link_up),          # PHY link (BMSR)
            leds.usb1.eq(bridge.pc_linked),        # PC MAC learned
            leds.usb2.eq(bridge.free_run),         # no ADAT input synced
            leds.sync1.eq(bridge.builder.synced_in[0]),
            leds.sync2.eq(bridge.builder.synced_in[1]),
            leds.sync3.eq(bridge.builder.synced_in[2]),
            leds.sync4.eq(bridge.mdio.phy_found_out),
            leds.active1.eq(bridge.stats_tx_frames[22]),
            leds.active2.eq(bridge.stats_rx_frames[22]),
        ]

        #
        # UART status dump (PLL sync domain)
        #

        # events from the rmii domain
        tx_frame = _pulse_to(
            m, bridge.mac_tx_valid & bridge.mac_tx_ready
            & bridge.mac_tx_last, "rmii", D, "ev_tx_frame")
        rx_frame = _pulse_to(
            m, bridge.mac_rx_valid & bridge.mac_rx_ready
            & bridge.mac_rx_last, "rmii", D, "ev_rx_frame")
        rx_error = _pulse_to(
            m, bridge.mac_rx_valid & bridge.mac_rx_ready
            & bridge.mac_rx_last & bridge.mac_rx_error,
            "rmii", D, "ev_rx_error")
        hello_tx = _pulse_to(
            m, bridge.discovery.hello_valid & bridge.discovery.hello_ready
            & bridge.discovery.hello_last, "rmii", D, "ev_hello_tx")
        hello_rx = _pulse_to(
            m, bridge.discovery.dbg_hello_rx, "rmii", D, "ev_hello_rx")

        # events from the fast domain
        build_block = _gray_counter_count(
            m, bridge.builder.prod_cnt_gray_out, "fast", D, "cnt_build")
        tx_drop = _pulse_to(
            m, bridge.builder.tx_drops_out, "fast", D, "ev_tx_drop")

        # events from the sync domain
        feed_block = _gray_counter_count(
            m, bridge.feeder.cons_cnt_gray_out, "sync", D, "cnt_feed")
        underflow = _pulse_to(
            m, transmitters[0].underflow_out | transmitters[1].underflow_out,
            "sync", D, "ev_underflow")

        # filtered-frame event: derive from the bridge stats increment is
        # awkward; count "rx_last while not accepted" via the parser state
        # instead (approximate, debug only): a frame end that is neither a
        # counted audio frame nor a hello is filtered.
        rx_any_end = _pulse_to(
            m, bridge.mac_rx_valid & bridge.mac_rx_ready
            & bridge.mac_rx_last, "rmii", D, "ev_rx_any")
        rx_strobe = _pulse_to(
            m, bridge.discovery.rx_frame_strobe, "rmii", D,
            "ev_rx_strobe")
        filtered = Signal(16)
        with m.If(rx_any_end & ~rx_frame & ~rx_strobe):
            m.d[D] += filtered.eq(filtered + 1)

        # status levels
        def level(sig, src, name):
            s = Signal(name=name)
            m.submodules += FFSynchronizer(sig, s, o_domain=D)
            return s

        def level_sig(sig, name):
            s = Signal.like(sig, name=name)
            m.submodules += FFSynchronizer(sig, s, o_domain=D)
            return s

        link_up = level(bridge.link_up, "sync", "st_link")
        phy_found = level(bridge.mdio.phy_found_out, "sync", "st_phy")
        pc_linked = level(bridge.pc_linked, "rmii", "st_pc")
        free_run = level(bridge.free_run, "fast", "st_free")
        synced = [level(bridge.builder.synced_in[i], "fast",
                        f"st_sync{i}") for i in range(3)]
        feeder_active = level(bridge.feeder.dbg_active, "sync", "st_fact")
        feeder_commit = level(bridge.feeder.dbg_committing, "sync",
                              "st_fcom")
        if self.ref_clk_mode == "input":
            refclk_level = level(rmii.ref_clk.i, "rmii", "st_refclk")
        else:
            refclk_level = Const(0)
        crs_level = level(rmii.crs_dv.i, "rmii", "st_crs")

        status0 = Signal(16)
        status1 = Signal(16)
        m.d.comb += [
            status0.eq(Cat(link_up, pc_linked, free_run,
                           synced[0], synced[1], synced[2], phy_found)),
            status1.eq(Cat(feeder_active, feeder_commit,
                           refclk_level, crs_level)),
        ]

        values = [
            _count(m, tx_frame, D, "c_tx_frames"),
            _count(m, rx_frame, D, "c_rx_frames"),
            _count(m, hello_tx, D, "c_hello_tx"),
            _count(m, hello_rx, D, "c_hello_rx"),
            build_block,
            feed_block,
            _count(m, rx_error, D, "c_rx_err"),
            _count(m, tx_drop, D, "c_tx_drop"),
            filtered,
            _count(m, underflow, D, "c_underflow"),
            status0,
            status1,
            level(bridge.discovery.linked_out, "rmii", "st_linked"),
            _count(m, _pulse_to(m, bridge.discovery.dbg_hello_due,
                                "rmii", D, "ev_hdue"), D, "c_hdue"),
            # MAC short-frame diagnostics (hello bring-up)
            _count(m, _pulse_to(m, mac_dbg["sink_frame"], "rmii", D,
                                "ev_mac_sfn"), D, "c_mac_sfn"),
            _count(m, _pulse_to(m, mac_dbg["sink_short"], "rmii", D,
                                "ev_mac_sfs"), D, "c_mac_sfs"),
            _count(m, _pulse_to(m, mac_dbg["phy_frame"], "rmii", D,
                                "ev_mac_pfn"), D, "c_mac_pfn"),
            _count(m, _pulse_to(m, mac_dbg["phy_short"], "rmii", D,
                                "ev_mac_pfs"), D, "c_mac_pfs"),
        ]

        # TX tap values: [sink_len, sink_count, mac_len, mac_count] then
        # the 16 captured bytes of each side as 8 u16 (little-endian).
        if self.debug_taps:
            sink_cap_s = [level_sig(v, f"st_scap{i}")
                          for i, v in enumerate(sink_cap)]
            mac_cap_s = [level_sig(v, f"st_mcap{i}")
                         for i, v in enumerate(mac_cap)]
            mac_pin_s = [level_sig(v, f"st_mpin{i}")
                         for i, v in enumerate(mac_pin)]
            values += [
                level_sig(sink_cap_len, "st_slen"),
                level_sig(sink_cap_count, "st_scnt"),
                level_sig(mac_cap_len, "st_mlen"),
                level_sig(mac_cap_count, "st_mcnt"),
                level_sig(mac_pin_len, "st_plen"),
                level_sig(mac_pin_count, "st_pcnt"),
            ]
            for arr in (sink_cap_s, mac_cap_s, mac_pin_s):
                for k in range(0, 16, 2):
                    values.append(Cat(arr[k], arr[k + 1]))
            sink_pay_s = [level_sig(v, f"st_spay{i}")
                          for i, v in enumerate(sink_pay)]
            for k in range(0, 16, 2):
                values.append(Cat(sink_pay_s[k], sink_pay_s[k + 1]))
        else:
            # keep the dump layout identical (6 lengths/counts, three
            # 16-byte captures, 16 payload bytes = 38 u16)
            values += [Const(0, 16)] * 38

        #
        # RX-side bring-up taps for input0 (IN1).  These answer "is the
        # ADAT receiver producing samples/frames at all?" independently of
        # the Ethernet path (signals are crossed into the UART domain the
        # same way as the other event taps):
        #   c_rx_en    receiver output_enable pulses while synced
        #              (~8 x 3200/s = 25600/s when decoding)
        #   c_rx_ch7   output_enable pulses for channel 7 (one per frame)
        #   c_rx_q     qualified NRZI edges (bit-clock recovery)
        #   c_rx_fdone collector latched a complete 8-channel frame
        #   c_rx_finc  collector saw a frame end with channels missing
        #   c_rx_wrap  collector ring wrapped (drives the block builder)
        #   rx_int     sync-counter latch (only meaningful while the
        #              decoder is acquiring; reads a small stale value in
        #              steady DECODE, where this counter is not running)
        #   rx_addr / rx_user / rx_state  last addr/data and decoder state
        #
        rx0 = receivers[0]
        bld = bridge.builder
        rx_en_pulse = _pulse_to(
            m, rx0.output_enable & rx0.synced_out, "fast", D, "ev_rx_en")
        rx_ch7_pulse = _pulse_to(
            m, rx0.output_enable & rx0.synced_out & (rx0.addr_out == 7),
            "fast", D, "ev_rx_ch7")
        rx_q_pulse = _pulse_to(
            m, rx0.dbg_qualified_edge, "fast", D, "ev_rx_q")
        rx_fdone_pulse = _pulse_to(
            m, bld.dbg_frame_done_out, "fast", D, "ev_rx_fdone")
        rx_finc_pulse = _pulse_to(
            m, bld.dbg_incomplete_out, "fast", D, "ev_rx_finc")
        rx_wrap_pulse = _pulse_to(
            m, bld.dbg_wrap_out, "fast", D, "ev_rx_wrap")

        rx_int = Signal(8, name="rx_int_latch")
        with m.If(rx0.dbg_qualified_edge):
            m.d.fast += rx_int.eq(rx0.dbg_interval)
        rx_int_s = level_sig(rx_int, "st_rx_int")
        rx_addr_s = level_sig(rx0.addr_out, "st_rx_addr")
        rx_user_s = level_sig(rx0.user_data_out, "st_rx_user")
        rx_state_s = level(rx0.dbg_sync_state, "fast", "st_rx_state")

        values += [
            _count(m, rx_en_pulse, D, "c_rx_en"),
            _count(m, rx_ch7_pulse, D, "c_rx_ch7"),
            _count(m, rx_q_pulse, D, "c_rx_q"),
            _count(m, rx_fdone_pulse, D, "c_rx_fdone"),
            _count(m, rx_finc_pulse, D, "c_rx_finc"),
            _count(m, rx_wrap_pulse, D, "c_rx_wrap"),
            Cat(rx_int_s, Const(0, 8)),
            Cat(rx_addr_s, Const(0, 13)),
            Cat(rx_user_s, Const(0, 12)),
            Cat(rx_state_s, Const(0, 15)),
        ]

        values += ref_mon_values

        platform.add_resources([Resource("uart_dbg", 0,
            Subsignal("tx", Pins("J_2:34", dir="o"),
                      Attrs(io_standard="3.3-V LVCMOS")))])
        uart = platform.request("uart_dbg", 0)

        # UART TX, 115200 8N1 from the 50 MHz local clock
        DIV = 434
        data = Signal(8)
        start = Signal()
        busy = Signal()
        phase = Signal(range(DIV + 1))
        bit_i = Signal(4)
        shift = Signal(8)
        txd = Signal(reset=1)
        m.d.comb += uart.tx.eq(txd)
        with m.If(busy):
            with m.If(phase == DIV - 1):
                m.d[D] += phase.eq(0)
                with m.If(bit_i == 9):
                    m.d[D] += [busy.eq(0), txd.eq(1)]
                with m.Elif(bit_i == 8):
                    m.d[D] += [bit_i.eq(9), txd.eq(1)]
                with m.Else():
                    m.d[D] += [bit_i.eq(bit_i + 1), txd.eq(shift[0]),
                               shift.eq(shift >> 1)]
            with m.Else():
                m.d[D] += phase.eq(phase + 1)
        with m.Else():
            with m.If(start):
                m.d[D] += [busy.eq(1), shift.eq(data), bit_i.eq(0),
                           phase.eq(0), txd.eq(0)]

        # dump every 250 ms: AA 01 <u16 LE per value> 5A (probe style)
        total = 2 + 2 * len(values) + 1
        period = 12_500_000
        timer = Signal(range(period))
        fire = Signal()
        idx = Signal(range(total + 1))
        dumping = Signal()
        m.d[D] += fire.eq(0)
        with m.If(timer == period - 1):
            m.d[D] += [timer.eq(0), fire.eq(1)]
        with m.Else():
            m.d[D] += timer.eq(timer + 1)
        with m.If(fire):
            m.d[D] += [dumping.eq(1), idx.eq(0)]
        with m.Elif(dumping & ~busy):
            with m.If(idx == total - 1):
                m.d[D] += dumping.eq(0)
            with m.Else():
                m.d[D] += idx.eq(idx + 1)

        byte_table = [0xAA, 0x01]
        for v in values:
            byte_table += [v[0:8], v[8:16]]
        byte_table += [0x5A]
        m.d.comb += [
            start.eq(fire | (dumping & ~busy)),
            data.eq(Array(byte_table)[Mux(idx < total, idx, 0)]),
        ]

        return m


if __name__ == "__main__":
    os.environ.setdefault("LUNA_PLATFORM",
                          "platforms:ADATFaceCycloneIV_EP4CGX150")
    top_level_cli(EtherADATInterface)
